public class MaquinaChocolate extends Maquina {
    protected float capacidad;

    public MaquinaChocolate() {
        super();
        capacidad = 0;
    }

    public MaquinaChocolate(String codigo, String marca, String modelo, float tarifa, float capacidad) {
        super(codigo, marca, modelo, tarifa);
        this.capacidad = capacidad;
    }

    public void setCapacidad(float newCapacidad) {
        capacidad = newCapacidad;
    }

    public float getCapacidad() {
        return capacidad;
    }

    @Override
    public float Cotizacion(int dias) {
        float total = tarifa * dias;
        total += 20 * capacidad * dias;
        return total;
    }

    @Override
    public String getTipo() {
        return "Chocolate";
    }

	@Override
	public void mostrarCaracteristicas() {
    	System.out.println("Capacidad: " + capacidad + " kg");
	}
}